
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_apbeint_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_apbeint", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([9.399240392026790e+01, 9.033937425004781e+01, 8.534458729791112e+01, 7.866464628559034e+01, 7.000939461712686e+01, 5.928968253605856e+01, 4.683608886432265e+01, 3.361162677576294e+01, 2.120545590987111e+01, 1.132962664377693e+01, 5.013992769892503e+00, 2.530240765109768e+00, 1.907247517327230e+00, 1.265589384799319e+00, 6.403158258918392e-01, 2.410056953883398e-01, 6.055937776415485e-02, 7.454500457308951e-03, 3.450497848073365e-04, 4.328963215214579e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


